fill(0,0,100,90); for(let i=-2;i<=2;i++) rect(K.x+i*U*0.4-U*0.12, mouthY-U*0.3, U*0.24, U*0.3); // upper teeth
// glowing eyes
fill(190,85,100,70+A.bass*30); rect(K.x-U*0.85,headY,U*0.6,U*0.28); rect(K.x+U*0.25,headY,U*0.6,U*0.28);
