pop();
// eat flash burst
if(K.flash>0){ push(); translate(mouthX,mouthY); blendMode(ADD);
  for(let i=0;i<12;i++){ const a=i/12*TWO_PI; const r=(18-K.flash)*U*0.2;
    fill(K.eatHue||30,80,100,K.flash*4); noStroke();
    ellipse(Math.cos(a)*r,Math.sin(a)*r,U*0.4,U*0.4); } pop(); }
pop();

const s=window.state; if(s.tt===undefined)s.tt=0; s.tt+=0.01; const d=s.tt;
